function open(prepared){editingProject=api.getProject();snapshot=clone(api.getState());if(!snapshot.projects.some(p=>p.id===editingProject))throw Error('Selecione uma obra no topo para gerar os vínculos.');if(prepared){let imported=importConfiguration(snapshot,editingProject,prepared);draft=imported.links;importNotes=imported.notes}else{draft=suggest(snapshot,editingProject);importNotes=[]}pending=false;$('#readerTitle').textContent='Conferir vínculos por grupo';draw();$('#reader').showModal()}
function draw(){let stages=snapshot.stages.filter(st=>st.project===editingProject),budget=snapshot.budgetStages.filter(st=>st.project===editingProject);$('#readerContent').innerHTML='<div class="reader-page forecast-editor">'+(importNotes.length?'<div class="notice neutral"><strong>Configuração pronta: '+draft.length+' vínculos. Confira as observações e clique em salvar.</strong><ul>'+importNotes.map(n=>'<li>'+h(n)+'</li>').join('')+'</ul></div>':'')+'<p>Confira as sugestões antes de salvar. Uma regra vincula um grupo inteiro do cronograma ao orçamento. Se vários grupos alimentam o mesmo orçamento, divida a participação entre eles, somando até 100% por item financeiro. Os itens sem vínculo aparecem como pendentes, sem desaparecer da previsão.</p><div class="table-wrap"><table class="forecast-sheet"><thead><tr><th>Grupo do cronograma</th><th>Atividades abrangidas</th><th>Grupo do orçamento</th><th>Participação no orçamento (%)</th><th>Distribuição</th><th>Conferência</th><th></th></tr></thead><tbody>'+draft.map((l,i)=>'<tr><td><select data-forecast-row="'+i+'" data-key="scheduleStage">'+options(stages.map(st=>[st.id,[D.planningCode(st),st.name].filter(Boolean).join(' · ')]),l.scheduleStage)+'</select></td><td>'+activities(snapshot,l.scheduleStage).length+'</td><td><select data-forecast-row="'+i+'" data-key="budgetStage">'+options(budget.map(st=>[st.id,[st.code,st.name+(budgetItems(snapshot,st.id).length?'':' (sem itens orçados)')].filter(Boolean).join(' · ')]),l.budgetStage)+'</select></td><td><input data-forecast-row="'+i+'" data-key="share" inputmode="decimal" value="'+h(l.share)+'"></td><td><select data-forecast-row="'+i+'" data-key="rule"><option value="linear" '+(l.rule==='linear'?'selected':'')+'>Durante a execução</option><option value="finish" '+(l.rule==='finish'?'selected':'')+'>Na conclusão do grupo</option></select></td><td>'+h(l.confidence||'Vínculo conferido anteriormente')+'</td><td><button class="text-btn red-text" data-forecast-remove="'+i+'">Remover</button></td></tr>').join('')+'</tbody></table></div><button class="button secondary" id="forecastAdd">+ Regra de grupo</button><p class="section-note">A sugestão usa nomes, códigos com descrição compatível ou a origem do orçamento. Correspondências duvidosas ficam sem vínculo. Uma regra de grupo pai também abrange suas subetapas. O total do orçamento nunca é multiplicado pelo número de atividades.</p><label><input type="checkbox" id="forecastReviewed"> Conferi os grupos, as participações e os critérios de previsão.</label><p id="forecastError" class="red-text" role="alert"></p><button class="button primary" id="forecastSave" disabled>Salvar vínculos e gerar previsão</button></div>';for(let el of document.querySelectorAll('[data-forecast-row]'))el.onchange=()=>{draft[el.dataset.forecastRow][el.dataset.key]=el.value;$('#forecastReviewed').checked=false;$('#forecastSave').disabled=true};for(let el of document.querySelectorAll('[data-forecast-remove]'))el.onclick=()=>{draft.splice(Number(el.dataset.forecastRemove),1);draw()};$('#forecastAdd').onclick=()=>{draft.push({id:id(),project:editingProject,scheduleStage:'',budgetStage:'',share:100,rule:'linear',confidence:'Configuração manual'});draw()};$('#forecastReviewed').onchange=()=>$('#forecastSave').disabled=!$('#forecastReviewed').checked;$('#forecastSave').onclick=async()=>{if(pending)return;try{if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Reabra a configuração antes de salvar.');let next=saveLinks(snapshot,editingProject,draft);pending=true;for(let el of document.querySelectorAll('.forecast-editor input,.forecast-editor select,.forecast-editor button'))el.disabled=true;let confirmed=await api.save(next);if(confirmed===false)throw Error('O servidor não confirmou os vínculos. Atualize os dados.');pending=false;$('#reader').close();api.render();api.toast('Vínculos salvos. A previsão acompanha as datas do cronograma.')}catch(e){pending=false;$('#forecastError').textContent=e.message;for(let el of document.querySelectorAll('.forecast-editor input,.forecast-editor select,.forecast-editor button'))el.disabled=false;$('#forecastReviewed').checked=false;$('#forecastSave').disabled=true}}}
function handle(action){try{if(action==='forecast-import'){if(!api.getState().projects.some(p=>p.id===api.getProject()))throw Error('Selecione uma obra no topo antes de importar.');let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{let file=input.files?.[0];if(!file)return;if(file.size>1000000)throw Error('Use o arquivo de configuração, com até 1 MB, e não o backup.');open(JSON.parse(await file.text()))}catch(e){api.toast(e.message)}};input.click();return true}if(action==='forecast-config'){open();return true}if(action==='forecast-csv'){let s=api.getState(),result=forecast(s,api.getProject()),quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"',data=[['Mês','Obra','Item','Quantidade estimada','Unidade','Valor a medir'],...result.rows.map(r=>[r.month==='undated'?'Sem datas':r.month==='unlinked'?'Sem vínculo':r.month,s.projects.find(p=>p.id===r.project)?.name,r.name,String(r.quantity).replace('.',','),r.unit,r.amount.toFixed(2).replace('.',',')])].map(row=>row.map(quote).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='previsao-medicoes-'+D.today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);return true}}catch(e){api.toast(e.message);return true}return false}
